insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-11', 't-values', 2, 'لاحظ معلم آثار إيذاء ظاهرة على طالب مع تغير سلوكي واضح. الواجب المهني:', '["تجاهل الأمر لأنه شأن أسري","الإبلاغ الفوري وفق الأنظمة المعتمدة لحماية الطفل","استجواب الطالب أمام زملائه","مواجهة ولي الأمر بالاتهام مباشرة"]'::jsonb, 1, 'حماية الطالب واجب نظامي وأخلاقي؛ يبلغ المعلم الجهات المختصة بالمدرسة وفق إجراءات حماية الطفل بسرية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-12', 't-values', 2, 'أفضل قناة لتواصل المعلم مع أولياء الأمور بشأن مستوى أبنائهم:', '["حساباته الشخصية في وسائل التواصل بلا ضوابط","القنوات الرسمية المعتمدة من المدرسة مع توثيق التواصل","الطلاب أنفسهم ينقلون الرسائل الشفهية","عدم التواصل مطلقاً"]'::jsonb, 1, 'التواصل المهني يكون عبر القنوات المعتمدة وبتوثيق مناسب، حفظاً للخصوصية والمهنية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-13', 't-values', 3, 'طلب منك ولي أمر متنفذ رفع درجات ابنه مجاملةً. التصرف المهني:', '["الاستجابة حفظاً للعلاقة","الاعتذار بلطف والتمسك بعدالة التقويم وعرض سبل الدعم المشروعة للطالب","رفع الدرجات مع تنبيه الطالب","تخفيض درجات بقية الطلاب"]'::jsonb, 1, 'الأمانة والعدل لا يقبلان المساومة؛ ويُعرض البديل المشروع: خطة تحسين ومتابعة ودعم إضافي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-14', 't-values', 2, 'من صور تعزيز الانتماء الوطني والقيم الوسطية في التدريس:', '["إثارة النعرات والجدل الطائفي","ربط الدروس بمنجزات الوطن وترسيخ التسامح والاعتدال ونبذ الغلو","الاكتفاء بالمناسبات الرسمية","ترك الموضوع للأسرة فقط"]'::jsonb, 1, 'غرس الاعتدال والانتماء مسؤولية مستمرة تتخلل المواقف الصفية والمناهج والأنشطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-01', 't-tech', 1, 'المعيار الأول لاختيار تطبيق تقني لاستخدامه في الدرس:', '["حداثته وشهرته","خدمته للهدف التعليمي وملاءمته للطلاب","مجانيته فقط","كثرة مؤثراته البصرية"]'::jsonb, 1, 'التقنية وسيلة لا غاية؛ العبرة بخدمة الهدف التعليمي وملاءمة المحتوى وخصائص المتعلمين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-02', 't-tech', 2, 'أراد معلم كيمياء تنفيذ تجربة خطرة يصعب إجراؤها واقعياً. الحل التقني الأنسب:', '["إلغاء التجربة نهائياً","مختبر افتراضي يحاكي التجربة بأمان","وصفها شفهياً فقط","تكليف الطلاب بها منزلياً"]'::jsonb, 1, 'المختبرات الافتراضية تحاكي التجارب الخطرة أو المكلفة بأمان مع الحفاظ على الخبرة العملية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-03', 't-tech', 2, 'درس يمزج بين لقاءات حضورية وأنشطة إلكترونية عبر منصة تعليمية يسمى تعلماً:', '["متزامناً فقط","مدمجاً","ذاتياً بحتاً","تقليدياً"]'::jsonb, 1, 'التعلم المدمج يجمع مزايا الحضوري (التفاعل المباشر) والإلكتروني (المرونة وتعدد المصادر).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-04', 't-tech', 2, 'بث المعلم درساً مباشراً عبر منصة في وقت محدد يتفاعل فيه الطلاب آنياً. هذا تعلم إلكتروني:', '["غير متزامن","متزامن","مدمج","معكوس"]'::jsonb, 1, 'المتزامن يجري في وقت واحد للجميع (بث مباشر)، وغير المتزامن يتاح الرجوع إليه في أي وقت.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-05', 't-tech', 2, 'من سلوكيات المواطنة الرقمية التي يغرسها المعلم:', '["نسخ الأبحاث من الإنترنت دون توثيق","التحقق من مصداقية المعلومات واحترام الملكية الفكرية وحماية الخصوصية","مشاركة كلمات المرور مع الأصدقاء","التنمر المستتر بحسابات وهمية"]'::jsonb, 1, 'المواطنة الرقمية: استخدام آمن قانوني أخلاقي للتقنية، ومنه التوثيق والتثبت وحفظ الخصوصية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-06', 't-tech', 2, 'وصل طالباً خبر مثير عبر وسائل التواصل وأراد نشره. المهارة التي يجب أن يدربه المعلم عليها أولاً:', '["سرعة إعادة النشر","التثبت من المصدر ومصداقية الخبر قبل التفاعل معه","جمع الإعجابات","حذف التطبيق"]'::jsonb, 1, 'التثبت من المصادر جوهر التربية الإعلامية الرقمية ويقي من ترويج الشائعات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-07', 't-tech', 2, 'طالب ذكاؤه عادي وتحصيله في القراءة متدنٍ جداً مقارنة بأقرانه مع أخطاء نوعية متكررة (قلب الحروف وحذفها) دون مشكلات حسية. الحالة الأقرب:', '["إعاقة عقلية","صعوبات تعلم (عسر قراءة)","تأخر دراسي عام بسبب الإهمال","اضطراب سلوكي"]'::jsonb, 1, 'التباين بين قدرة عقلية عادية وتحصيل متدنٍ في مهارة محددة بأخطاء نوعية سمة صعوبات التعلم النمائية الأكاديمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-08', 't-tech', 2, 'طالب كثير الحركة مندفع مشتت الانتباه (ADHD). من الممارسات الصفية الداعمة له:', '["إجلاسه آخر الصف بعيداً","حرمانه من الحركة كلياً","تقريبه من المعلم وتجزئة المهام ومنحه مهام حركية مشروعة","توبيخه المتكرر أمام زملائه"]'::jsonb, 2, 'يدعم بجلوس قريب يقلل المشتتات، ومهام قصيرة، وقنوات حركة مقبولة، وتعزيز فوري.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-09', 't-tech', 2, 'طالب موهوب ينهي المهام سريعاً ثم يشاغب لملله. المعالجة التربوية الأنسب:', '["أنشطة إثرائية ومهام تفكير عليا تناسب قدراته","زيادة الواجبات الروتينية المتكررة نفسها","تجاهله لأنه متفوق","معاقبته على المشاغبة فقط"]'::jsonb, 0, 'الموهوب يحتاج إثراء وتحدياً معرفياً؛ الملل مصدر مشاغبته، والمزيد من الروتين يفاقمها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-10', 't-tech', 3, 'الوثيقة التي تحدد أهدافاً وخدمات تعليمية فردية لطالب من ذوي الإعاقة ويشارك في إعدادها فريق متعدد التخصصات مع الأسرة:', '["جدول المواصفات","الخطة التربوية الفردية (IEP)","سجل الدرجات","خطة النشاط اللاصفي"]'::jsonb, 1, 'الخطة التربوية الفردية تبنى على تشخيص دقيق وتحدد الأهداف والخدمات المساندة وتراجع دورياً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-11', 't-tech', 2, 'الفلسفة التربوية وراء دمج ذوي الاحتياجات الخاصة في المدارس العادية:', '["تخفيض التكاليف فقط","حقهم في بيئة أقل عزلاً وأثرها الاجتماعي والنفسي الإيجابي على الجميع","عدم توفر مدارس خاصة","تخفيف أعباء الأسر"]'::jsonb, 1, 'الدمج حق تربوي يعزز التقبل والانتماء وينمي المهارات الاجتماعية لذوي الإعاقة وأقرانهم معاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-12', 't-tech', 2, 'في صفه طالب ضعيف سمع. من الممارسات الصحيحة للمعلم:', '["التحدث وهو مدير ظهره للسبورة","إجلاسه في مقدمة الصف ومواجهته عند الحديث بوضوح","تجاهل مشاركته توفيراً للوقت","رفع الصوت بصراخ دائم"]'::jsonb, 1, 'المقعد الأمامي ومواجهة الطالب أثناء الكلام (لقراءة الشفاه) ووضوح النطق ممارسات داعمة أساسية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
